test('maintenance PRs are recognised by branch, by title, and by author', () => {
  assert.ok(isMaintenance(pr(1, { ref: 'claudinite/fleet-usage/2026-08-08' })), 'engine branch');
  assert.ok(isMaintenance(pr(2, { title: 'Claudinite: recompute the aggregate' })), 'engine title');
  assert.ok(isMaintenance(pr(3, { type: 'Bot' })), 'a bot author');
  assert.ok(isMaintenance(pr(4, { login: 'dependabot[bot]' })), 'a bot login');
});

test('the fleet\'s own dispatch issues are machine-filed, not accomplishments', () => {
  // Regression, from the first real backfill: three of one day's six shortlist slots
  // were `[claudinite-task]` issues. They do not merely appear — they WIN, because an
  // issue's weight counts its discussion and the executor comments on every stage.
  // The queue's vocabulary is the one that matters going forward — every occurrence
  // of every task in every member is one of these. A filter that knew only the
  // retired prefix would hand the whole fleet's scheduled work to the shortlist.
  assert.ok(isMachineIssue({ title: '[claudinite-work] claudinite-growth/growth-extract' }));
  assert.ok(isMachineIssue({ title: '[claudinite-work] claudinite-fleet-sheepdog/fleet-baseline (Alpha Beta)' }));
  // the schedule board (#1115): rewritten by every verdict change, and a body
  // that would otherwise WIN the brief on sheer accumulated weight
  assert.ok(isMachineIssue({ title: '[claudinite-schedule] the schedule board' }));
  assert.ok(isMachineIssue({ title: '[claudinite-task] claudinite-growth/growth-extract d2026-07-26' }));

